+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * A filter understood by {@link CustomerRepository}: a name search and a set of
+ * acceptable statuses. Both parts are applied by the backend.
+ *
+ * @param name      free text; split on whitespace into terms, every term must
+ *                  appear in the first name or the last name. Blank matches
+ *                  every customer.
+ * @param statuses  acceptable statuses; empty matches every customer
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** Whether the given customer satisfies both the name and the status filter. */
+    public boolean matches(Customer customer) {
+        return matchesStatus(customer) && matchesName(customer);
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private boolean matchesName(Customer customer) {
+        List<String> terms = nameTerms();
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private List<String> nameTerms() {
+        String trimmed = name.trim();
+        if (trimmed.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.stream(trimmed.split("\\s+")).map(CustomerFilter::normalize).toList();
+    }
+
+    private static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return decomposed.replaceAll("\\p{M}", "").toLowerCase(Locale.ROOT);
+    }
+}
